-- Payment settlement custody V3: clearing -> in transit -> custodian-confirmed destination.
alter table public.payment_settlements
  add column if not exists status text not null default 'completed',
  add column if not exists requested_at timestamptz,
  add column if not exists received_at timestamptz,
  add column if not exists destination_responsible_user_id uuid references public.users(id) on delete restrict,
  add column if not exists receiver_task_id uuid references public.operations_tasks(id) on delete restrict,
  add column if not exists receiver_confirmed_by uuid references public.users(id) on delete restrict,
  add column if not exists receiver_note text,
  add column if not exists failure_reason text,
  add column if not exists source_net_ledger_entry_id uuid references public.payment_ledger(id) on delete restrict,
  add column if not exists fee_ledger_entry_id uuid references public.payment_ledger(id) on delete restrict,
  add column if not exists destination_payment_ledger_entry_id uuid references public.payment_ledger(id) on delete restrict,
  add column if not exists destination_cash_ledger_entry_id uuid references public.cash_ledger(id) on delete restrict,
  add column if not exists updated_at timestamptz not null default now();
update public.payment_settlements set status='completed',requested_at=coalesce(requested_at,settled_at,created_at),received_at=coalesce(received_at,settled_at),updated_at=coalesce(updated_at,created_at) where status is null or status='completed';
alter table public.payment_settlements drop constraint if exists payment_settlements_status_check;
alter table public.payment_settlements add constraint payment_settlements_status_check check(status in ('awaiting_receiver','completed','exception'));
create index if not exists payment_settlements_branch_status_idx on public.payment_settlements(branch_id,status,requested_at desc);
create unique index if not exists payment_settlements_receiver_task_unique on public.payment_settlements(receiver_task_id) where receiver_task_id is not null;

create or replace function private.resolve_settlement_destination_custodian_v3(p_branch_id uuid,p_target_kind text,p_target_account_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_uid uuid;v_name text;v_account_name text;v_balance numeric;begin
 if p_target_kind='safe' then select ca.custodian_user_id,u.name,ca.name,private.cash_account_balance(ca.id) into v_uid,v_name,v_account_name,v_balance from public.cash_accounts ca left join public.users u on u.id=ca.custodian_user_id where ca.id=p_target_account_id and ca.branch_id=p_branch_id and ca.account_type='branch_safe' and ca.active;
 elsif p_target_kind='bank' then select pa.custodian_user_id,u.name,pa.name,private.payment_account_balance(pa.id) into v_uid,v_name,v_account_name,v_balance from public.payment_accounts pa left join public.users u on u.id=pa.custodian_user_id where pa.id=p_target_account_id and pa.branch_id=p_branch_id and pa.account_type='bank' and pa.active;
 else return null; end if;
 if v_account_name is null then return null;end if;
 return jsonb_build_object('account_name',v_account_name,'responsible_user_id',v_uid,'responsible_user_name',v_name,'balance',round(coalesce(v_balance,0),2));
end;$$;
revoke all on function private.resolve_settlement_destination_custodian_v3(uuid,text,uuid) from public,anon,authenticated;

create or replace function public.get_finance_settlement_workspace_v3(p_branch_id uuid,p_limit integer default 80)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_limit integer:=least(greatest(coalesce(p_limit,80),10),200);v_can_manage boolean:=false;v_sources jsonb:='[]';v_targets jsonb:='[]';v_recent jsonb:='[]';begin
 if auth.uid() is null then raise exception using errcode='42501',message='AUTH_REQUIRED';end if;
 if not public.has_branch_access(auth.uid(),p_branch_id) then raise exception using errcode='42501',message='FINANCE_BRANCH_ACCESS_DENIED';end if;
 if not(private.staff_is_super_admin(auth.uid()) or public.staff_has_permission('finance.view',p_branch_id) or public.staff_has_permission('finance.manage',p_branch_id)) then raise exception using errcode='42501',message='FINANCE_VIEW_DENIED';end if;
 v_can_manage:=private.staff_is_super_admin(auth.uid()) or public.staff_has_permission('finance.manage',p_branch_id);
 select coalesce(jsonb_agg(jsonb_build_object('account_id',a.id,'account_name',a.name,'provider_code',a.provider_code,'active',a.active,'balance',round(private.payment_account_balance(a.id),2),'payment_method_id',pm.id,'payment_method_code',coalesce(pm.code,a.provider_code),'payment_method_name',coalesce(pm.name,a.name),'method_type',coalesce(pm.method_type,'other'),'method_active',pm.active,'fee_type',coalesce(pm.fee_type,'none'),'fee_value',coalesce(pm.fee_value,0),'fee_bearer',coalesce(pm.fee_bearer,'business'),'require_reference',coalesce(pm.require_reference,false)) order by case when private.payment_account_balance(a.id)>0.005 then 0 else 1 end,coalesce(pm.sort_order,999),a.name),'[]') into v_sources from public.payment_accounts a left join public.pos_payment_methods pm on pm.branch_id=a.branch_id and pm.settlement_account_id=a.id where a.branch_id=p_branch_id and a.account_type='gateway_clearing' and(a.active or pm.id is not null or abs(private.payment_account_balance(a.id))>0.005);
 with targets as(select ca.id account_id,'safe'::text target_kind,ca.name,private.cash_account_balance(ca.id) balance,ca.custodian_user_id,u.name responsible_user_name,ca.active from public.cash_accounts ca left join public.users u on u.id=ca.custodian_user_id where ca.branch_id=p_branch_id and ca.account_type='branch_safe' and ca.active union all select pa.id,'bank',pa.name,private.payment_account_balance(pa.id),pa.custodian_user_id,u.name,pa.active from public.payment_accounts pa left join public.users u on u.id=pa.custodian_user_id where pa.branch_id=p_branch_id and pa.account_type='bank' and pa.active) select coalesce(jsonb_agg(jsonb_build_object('account_id',account_id,'target_kind',target_kind,'name',name,'balance',round(balance,2),'responsible_user_id',custodian_user_id,'responsible_user_name',responsible_user_name,'assignable',custodian_user_id is not null) order by case target_kind when 'safe' then 0 else 1 end,name),'[]') into v_targets from targets;
 select coalesce(jsonb_agg(jsonb_build_object('settlement_id',s.id,'request_id',s.request_id,'status',s.status,'payment_method',s.payment_method,'payment_method_name',coalesce(s.payment_method_name_snapshot,s.payment_method),'source_account_id',s.clearing_account_id,'source_account_name',coalesce(s.source_account_name_snapshot,src.name),'target_kind',s.target_kind,'target_account_id',case when s.target_kind='safe' then s.cash_account_id else s.bank_account_id end,'target_account_name',coalesce(s.target_account_name_snapshot,tca.name,tpa.name),'gross_amount',round(s.gross_amount,2),'fee_amount',round(s.fee_amount,2),'net_amount',round(s.net_amount,2),'provider_reference',s.provider_reference,'note',s.note,'requested_at',coalesce(s.requested_at,s.settled_at),'received_at',s.received_at,'settled_at',s.settled_at,'responsible_user_id',s.destination_responsible_user_id,'responsible_user_name',ru.name,'receiver_task_id',s.receiver_task_id,'receiver_task_status',ot.status,'receiver_confirmed_by',s.receiver_confirmed_by,'receiver_confirmed_by_name',rc.name,'receiver_note',s.receiver_note,'failure_reason',s.failure_reason,'created_by',s.created_by,'created_by_name',cu.name) order by coalesce(s.requested_at,s.settled_at) desc),'[]') into v_recent from(select * from public.payment_settlements where branch_id=p_branch_id order by coalesce(requested_at,settled_at) desc limit v_limit)s left join public.payment_accounts src on src.id=s.clearing_account_id left join public.payment_accounts tpa on tpa.id=s.bank_account_id left join public.cash_accounts tca on tca.id=s.cash_account_id left join public.users ru on ru.id=s.destination_responsible_user_id left join public.users rc on rc.id=s.receiver_confirmed_by left join public.users cu on cu.id=s.created_by left join public.operations_tasks ot on ot.id=s.receiver_task_id;
 return jsonb_build_object('version',3,'branch_id',p_branch_id,'permissions',jsonb_build_object('can_manage',v_can_manage),'sources',v_sources,'targets',v_targets,'recent_settlements',v_recent,'generated_at',now());
end;$$;

create or replace function public.create_payment_settlement_v3(p_request_id uuid,p_branch_id uuid,p_source_account_id uuid,p_target_kind text,p_target_account_id uuid,p_gross_amount numeric,p_fee_amount numeric default 0,p_provider_reference text default null,p_note text default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare src public.payment_accounts%rowtype;pm public.pos_payment_methods%rowtype;existing public.payment_settlements%rowtype;v_target jsonb;v_resp uuid;v_resp_name text;v_target_name text;v_gross numeric;v_fee numeric;v_net numeric;v_balance numeric;v_method text;v_method_name text;v_ref text:=nullif(btrim(coalesce(p_provider_reference,'')),'');v_note text:=nullif(btrim(coalesce(p_note,'')),'');v_fp text;v_id uuid;v_task uuid;v_out uuid;v_fee_id uuid;begin
 if auth.uid() is null then raise exception using errcode='42501',message='AUTH_REQUIRED';end if;if not public.has_branch_access(auth.uid(),p_branch_id) then raise exception using errcode='42501',message='FINANCE_BRANCH_ACCESS_DENIED';end if;if not(private.staff_is_super_admin(auth.uid()) or public.staff_has_permission('finance.manage',p_branch_id)) then raise exception using errcode='42501',message='FINANCE_MANAGE_DENIED';end if;if p_request_id is null or p_source_account_id is null or p_target_account_id is null or p_target_kind not in('safe','bank') then raise exception using errcode='22023',message='SETTLEMENT_REQUEST_INVALID';end if;
 begin v_gross:=round(p_gross_amount,2);v_fee:=round(coalesce(p_fee_amount,0),2);exception when others then raise exception using errcode='22023',message='SETTLEMENT_AMOUNT_INVALID';end;if v_gross is null or v_gross<=0 or v_fee<0 or v_fee>=v_gross or v_gross::text in('NaN','Infinity','-Infinity') or v_fee::text in('NaN','Infinity','-Infinity') then raise exception using errcode='22023',message='SETTLEMENT_AMOUNT_INVALID';end if;v_net:=round(v_gross-v_fee,2);
 select * into src from public.payment_accounts where id=p_source_account_id and branch_id=p_branch_id and account_type='gateway_clearing';if src.id is null then raise exception using errcode='22023',message='SETTLEMENT_SOURCE_UNAVAILABLE';end if;select * into pm from public.pos_payment_methods where branch_id=p_branch_id and settlement_account_id=src.id order by active desc,sort_order,updated_at desc limit 1;v_method:=coalesce(nullif(pm.code,''),src.provider_code);v_method_name:=coalesce(nullif(pm.name,''),src.name);if coalesce(pm.require_reference,false) and v_ref is null then raise exception using errcode='22023',message='SETTLEMENT_REFERENCE_REQUIRED';end if;
 v_target:=private.resolve_settlement_destination_custodian_v3(p_branch_id,p_target_kind,p_target_account_id);if v_target is null then raise exception using errcode='22023',message='SETTLEMENT_TARGET_UNAVAILABLE';end if;v_resp:=nullif(v_target->>'responsible_user_id','')::uuid;v_resp_name:=v_target->>'responsible_user_name';v_target_name:=v_target->>'account_name';if v_resp is null then raise exception using errcode='22023',message='SETTLEMENT_TARGET_HAS_NO_RESPONSIBLE';end if;if not exists(select 1 from public.users u where u.id=v_resp and coalesce(u.active,true) and public.has_branch_access(u.id,p_branch_id)) then raise exception using errcode='22023',message='SETTLEMENT_TARGET_RESPONSIBLE_UNAVAILABLE';end if;
 v_fp:=md5(jsonb_build_array(p_branch_id,p_source_account_id,p_target_kind,p_target_account_id,v_gross,v_fee,v_ref,v_note)::text);perform pg_advisory_xact_lock(hashtextextended('finance-settlement-request:'||p_request_id::text,76));select * into existing from public.payment_settlements where request_id=p_request_id;if existing.id is not null then if existing.request_fingerprint is distinct from v_fp then raise exception using errcode='22023',message='REQUEST_CONFLICT';end if;return jsonb_build_object('ok',true,'idempotent',true,'settlement_id',existing.id,'status',existing.status,'receiver_task_id',existing.receiver_task_id,'net_amount',existing.net_amount);end if;
 perform pg_advisory_xact_lock(hashtextextended('payment-account:'||src.id::text,42));v_balance:=private.payment_account_balance(src.id);if v_gross>round(v_balance,2)+0.005 then raise exception using errcode='22023',message='INSUFFICIENT_SETTLEMENT_BALANCE';end if;
 insert into public.payment_settlements(branch_id,payment_method,clearing_account_id,bank_account_id,cash_account_id,gross_amount,fee_amount,net_amount,provider_reference,note,created_by,request_id,request_fingerprint,target_kind,source_account_name_snapshot,target_account_name_snapshot,payment_method_name_snapshot,status,requested_at,destination_responsible_user_id) values(p_branch_id,v_method,src.id,case when p_target_kind='bank' then p_target_account_id end,case when p_target_kind='safe' then p_target_account_id end,v_gross,v_fee,v_net,v_ref,v_note,auth.uid(),p_request_id,v_fp,p_target_kind,src.name,v_target_name,v_method_name,'awaiting_receiver',now(),v_resp) returning id into v_id;
 insert into public.payment_ledger(account_id,branch_id,settlement_id,entry_type,signed_amount,payment_method,external_reference,description,metadata,created_by) values(src.id,p_branch_id,v_id,'finance_settlement_pending_out',-v_net,v_method,v_ref,'صافي تسوية قيد الاستلام لدى '||v_target_name,jsonb_build_object('target_kind',p_target_kind,'target_account_id',p_target_account_id,'responsible_user_id',v_resp,'request_id',p_request_id),auth.uid()) returning id into v_out;
 if v_fee>0 then insert into public.payment_ledger(account_id,branch_id,settlement_id,entry_type,signed_amount,payment_method,external_reference,description,metadata,created_by) values(src.id,p_branch_id,v_id,'finance_settlement_fee',-v_fee,v_method,v_ref,'عمولة/رسوم تسوية '||v_method_name,jsonb_build_object('request_id',p_request_id,'gross_amount',v_gross),auth.uid()) returning id into v_fee_id;end if;
 insert into public.operations_tasks(branch_id,task_type,source_kind,source_id,amount,priority,status,title,description,claimed_by,claimed_at,metadata,created_by) values(p_branch_id,'treasury_disbursement','finance_payment_settlement_receipt',v_id,v_net,'high','claimed','استلام تسوية '||v_method_name,'أكد وصول صافي '||to_char(v_net,'FM9999999990.00')||' ج.م إلى '||v_target_name,v_resp,now(),jsonb_build_object('settlement_id',v_id,'source_account_id',src.id,'target_kind',p_target_kind,'target_account_id',p_target_account_id,'gross_amount',v_gross,'fee_amount',v_fee,'net_amount',v_net,'provider_reference',v_ref,'sensitive',true),auth.uid()) returning id into v_task;
 update public.payment_settlements set receiver_task_id=v_task,source_net_ledger_entry_id=v_out,fee_ledger_entry_id=v_fee_id,updated_at=now() where id=v_id;insert into public.operations_task_events(task_id,event_type,actor_id,note,metadata) values(v_task,'assigned',auth.uid(),'تم إسناد استلام التسوية إلى مسؤول العهدة',jsonb_build_object('responsible_user_id',v_resp,'settlement_id',v_id));return jsonb_build_object('ok',true,'idempotent',false,'settlement_id',v_id,'status','awaiting_receiver','receiver_task_id',v_task,'responsible_user_id',v_resp,'responsible_user_name',v_resp_name,'source_account_name',src.name,'target_account_name',v_target_name,'gross_amount',v_gross,'fee_amount',v_fee,'net_amount',v_net,'source_balance_after',private.payment_account_balance(src.id));
end;$$;

create or replace function public.get_my_payment_settlement_tasks_v3(p_limit integer default 30) returns jsonb language plpgsql stable security definer set search_path='' as $$declare v_items jsonb;begin if auth.uid() is null then raise exception using errcode='42501',message='AUTH_REQUIRED';end if;select coalesce(jsonb_agg(jsonb_build_object('task_id',t.id,'task_status',t.status,'settlement_id',s.id,'branch_id',s.branch_id,'payment_method_name',coalesce(s.payment_method_name_snapshot,s.payment_method),'source_account_name',s.source_account_name_snapshot,'target_kind',s.target_kind,'target_account_name',s.target_account_name_snapshot,'gross_amount',round(s.gross_amount,2),'fee_amount',round(s.fee_amount,2),'net_amount',round(s.net_amount,2),'provider_reference',s.provider_reference,'requested_at',s.requested_at,'status',s.status) order by s.requested_at desc),'[]') into v_items from public.operations_tasks t join public.payment_settlements s on s.receiver_task_id=t.id where t.source_kind='finance_payment_settlement_receipt' and t.claimed_by=auth.uid() and t.status in('claimed','in_progress') limit least(greatest(coalesce(p_limit,30),1),100);return jsonb_build_object('version',3,'items',v_items,'generated_at',now());end;$$;

create or replace function public.confirm_payment_settlement_receipt_v3(p_task_id uuid,p_note text) returns jsonb language plpgsql security definer set search_path='' as $$declare t public.operations_tasks%rowtype;s public.payment_settlements%rowtype;v_target jsonb;v_resp uuid;v_note text:=nullif(btrim(coalesce(p_note,'')),'');v_ledger uuid;v_balance numeric;begin if auth.uid() is null then raise exception using errcode='42501',message='AUTH_REQUIRED';end if;if v_note is null or length(v_note)<3 then raise exception using errcode='22023',message='SETTLEMENT_RECEIPT_NOTE_REQUIRED';end if;select * into t from public.operations_tasks where id=p_task_id for update;if t.id is null or t.source_kind<>'finance_payment_settlement_receipt' then raise exception using errcode='22023',message='SETTLEMENT_TASK_NOT_FOUND';end if;select * into s from public.payment_settlements where id=t.source_id for update;if s.id is null then raise exception using errcode='22023',message='SETTLEMENT_NOT_FOUND';end if;if s.status='completed' then return jsonb_build_object('ok',true,'idempotent',true,'settlement_id',s.id,'status',s.status);end if;if t.claimed_by is distinct from auth.uid() then raise exception using errcode='42501',message='SETTLEMENT_TASK_NOT_OWNER';end if;if t.status not in('claimed','in_progress') or s.status<>'awaiting_receiver' then raise exception using errcode='55000',message='SETTLEMENT_NOT_CONFIRMABLE';end if;v_target:=private.resolve_settlement_destination_custodian_v3(s.branch_id,s.target_kind,case when s.target_kind='safe' then s.cash_account_id else s.bank_account_id end);if v_target is null then raise exception using errcode='55000',message='SETTLEMENT_TARGET_UNAVAILABLE';end if;v_resp:=nullif(v_target->>'responsible_user_id','')::uuid;if v_resp is distinct from auth.uid() or s.destination_responsible_user_id is distinct from auth.uid() then raise exception using errcode='55000',message='SETTLEMENT_RESPONSIBILITY_CHANGED';end if;if s.target_kind='bank' then insert into public.payment_ledger(account_id,branch_id,settlement_id,entry_type,signed_amount,payment_method,external_reference,description,metadata,created_by) values(s.bank_account_id,s.branch_id,s.id,'finance_settlement_in',s.net_amount,s.payment_method,s.provider_reference,'استلام تسوية من '||coalesce(s.source_account_name_snapshot,s.payment_method),jsonb_build_object('receiver_task_id',t.id),auth.uid()) returning id into v_ledger;v_balance:=private.payment_account_balance(s.bank_account_id);update public.payment_settlements set destination_payment_ledger_entry_id=v_ledger where id=s.id;else insert into public.cash_ledger(account_id,branch_id,user_id,entry_type,signed_amount,reference_type,reference_id,description,metadata,created_by) values(s.cash_account_id,s.branch_id,auth.uid(),'payment_settlement_in',s.net_amount,'payment_settlement',s.id,'استلام تسوية من '||coalesce(s.source_account_name_snapshot,s.payment_method),jsonb_build_object('receiver_task_id',t.id,'payment_method',s.payment_method,'provider_reference',s.provider_reference),auth.uid()) returning id into v_ledger;v_balance:=private.cash_account_balance(s.cash_account_id);update public.payment_settlements set destination_cash_ledger_entry_id=v_ledger where id=s.id;end if;update public.payment_settlements set status='completed',received_at=now(),receiver_confirmed_by=auth.uid(),receiver_note=v_note,failure_reason=null,updated_at=now() where id=s.id;update public.operations_tasks set status='completed',completed_by=auth.uid(),completed_at=now(),failure_reason=null,metadata=coalesce(metadata,'{}')||jsonb_build_object('receipt_note',v_note,'destination_ledger_entry_id',v_ledger),updated_at=now() where id=t.id;insert into public.operations_task_events(task_id,event_type,actor_id,note,metadata) values(t.id,'completed',auth.uid(),v_note,jsonb_build_object('settlement_id',s.id,'destination_ledger_entry_id',v_ledger));return jsonb_build_object('ok',true,'idempotent',false,'settlement_id',s.id,'status','completed','net_amount',s.net_amount,'destination_balance_after',round(v_balance,2),'destination_ledger_entry_id',v_ledger);end;$$;

create or replace function public.reject_payment_settlement_receipt_v3(p_task_id uuid,p_reason text) returns jsonb language plpgsql security definer set search_path='' as $$declare t public.operations_tasks%rowtype;s public.payment_settlements%rowtype;v_reason text:=nullif(btrim(coalesce(p_reason,'')),'');begin if auth.uid() is null then raise exception using errcode='42501',message='AUTH_REQUIRED';end if;if v_reason is null or length(v_reason)<3 then raise exception using errcode='22023',message='SETTLEMENT_REJECTION_REASON_REQUIRED';end if;select * into t from public.operations_tasks where id=p_task_id for update;if t.id is null or t.source_kind<>'finance_payment_settlement_receipt' then raise exception using errcode='22023',message='SETTLEMENT_TASK_NOT_FOUND';end if;select * into s from public.payment_settlements where id=t.source_id for update;if s.id is null then raise exception using errcode='22023',message='SETTLEMENT_NOT_FOUND';end if;if t.claimed_by is distinct from auth.uid() then raise exception using errcode='42501',message='SETTLEMENT_TASK_NOT_OWNER';end if;if t.status not in('claimed','in_progress') or s.status<>'awaiting_receiver' then raise exception using errcode='55000',message='SETTLEMENT_NOT_REJECTABLE';end if;update public.payment_settlements set status='exception',failure_reason=v_reason,updated_at=now() where id=s.id;update public.operations_tasks set status='failed',failure_reason=v_reason,completed_by=auth.uid(),completed_at=now(),updated_at=now() where id=t.id;insert into public.operations_task_events(task_id,event_type,actor_id,note,metadata) values(t.id,'failed',auth.uid(),v_reason,jsonb_build_object('settlement_id',s.id));return jsonb_build_object('ok',true,'settlement_id',s.id,'status','exception','net_amount',s.net_amount);end;$$;

create or replace function public.retry_payment_settlement_receipt_v3(p_settlement_id uuid,p_note text) returns jsonb language plpgsql security definer set search_path='' as $$declare s public.payment_settlements%rowtype;t public.operations_tasks%rowtype;v_target jsonb;v_resp uuid;v_name text;v_note text:=nullif(btrim(coalesce(p_note,'')),'');begin if auth.uid() is null then raise exception using errcode='42501',message='AUTH_REQUIRED';end if;select * into s from public.payment_settlements where id=p_settlement_id for update;if s.id is null then raise exception using errcode='22023',message='SETTLEMENT_NOT_FOUND';end if;if not(private.staff_is_super_admin(auth.uid()) or public.staff_has_permission('finance.manage',s.branch_id)) then raise exception using errcode='42501',message='FINANCE_MANAGE_DENIED';end if;if s.status<>'exception' then raise exception using errcode='55000',message='SETTLEMENT_NOT_RETRYABLE';end if;if v_note is null or length(v_note)<3 then raise exception using errcode='22023',message='SETTLEMENT_RETRY_NOTE_REQUIRED';end if;v_target:=private.resolve_settlement_destination_custodian_v3(s.branch_id,s.target_kind,case when s.target_kind='safe' then s.cash_account_id else s.bank_account_id end);if v_target is null then raise exception using errcode='55000',message='SETTLEMENT_TARGET_UNAVAILABLE';end if;v_resp:=nullif(v_target->>'responsible_user_id','')::uuid;v_name:=v_target->>'responsible_user_name';if v_resp is null then raise exception using errcode='55000',message='SETTLEMENT_TARGET_HAS_NO_RESPONSIBLE';end if;select * into t from public.operations_tasks where id=s.receiver_task_id for update;if t.id is null then raise exception using errcode='55000',message='SETTLEMENT_TASK_NOT_FOUND';end if;update public.operations_tasks set status='claimed',claimed_by=v_resp,claimed_at=now(),started_at=null,completed_by=null,completed_at=null,failure_reason=null,metadata=coalesce(metadata,'{}')||jsonb_build_object('retry_note',v_note,'retry_at',now(),'retry_by',auth.uid()),updated_at=now() where id=t.id;update public.payment_settlements set status='awaiting_receiver',destination_responsible_user_id=v_resp,failure_reason=null,updated_at=now() where id=s.id;insert into public.operations_task_events(task_id,event_type,actor_id,note,metadata) values(t.id,'reassigned',auth.uid(),v_note,jsonb_build_object('responsible_user_id',v_resp,'settlement_id',s.id));return jsonb_build_object('ok',true,'settlement_id',s.id,'status','awaiting_receiver','task_id',t.id,'responsible_user_id',v_resp,'responsible_user_name',v_name);end;$$;

revoke all on function public.get_finance_settlement_workspace_v3(uuid,integer) from public,anon;revoke all on function public.create_payment_settlement_v3(uuid,uuid,uuid,text,uuid,numeric,numeric,text,text) from public,anon;revoke all on function public.get_my_payment_settlement_tasks_v3(integer) from public,anon;revoke all on function public.confirm_payment_settlement_receipt_v3(uuid,text) from public,anon;revoke all on function public.reject_payment_settlement_receipt_v3(uuid,text) from public,anon;revoke all on function public.retry_payment_settlement_receipt_v3(uuid,text) from public,anon;
grant execute on function public.get_finance_settlement_workspace_v3(uuid,integer) to authenticated,service_role;grant execute on function public.create_payment_settlement_v3(uuid,uuid,uuid,text,uuid,numeric,numeric,text,text) to authenticated,service_role;grant execute on function public.get_my_payment_settlement_tasks_v3(integer) to authenticated,service_role;grant execute on function public.confirm_payment_settlement_receipt_v3(uuid,text) to authenticated,service_role;grant execute on function public.reject_payment_settlement_receipt_v3(uuid,text) to authenticated,service_role;grant execute on function public.retry_payment_settlement_receipt_v3(uuid,text) to authenticated,service_role;
